// The spectator fold on fake arena runs (bot-backed fake models behind the LLM pipe, generated by
// the orchestrator): a fold that follows `match.jsonl` while it is being written, reading complete
// lines only from chunks cut anywhere (partial lines included), ends with the steps and the frame
// of a fold of the whole file; LLM turns are importance-1 items whose messages name their turn; the
// annotations fold of `llm_calls.jsonl` and `replies.jsonl` gives each LLM turn its rounds, fake
// reasoning and costs, and never a request id, an error message or a refusal explanation; nothing
// served carries the run's id key. Performance figures are printed (a 7-day run with
// `PERFIDIA_BENCH=1`).

import { describe, expect, test } from "bun:test";
import { canonicalJson } from "@perfidia/engine/core";
import { LogLineSchema, type HeaderLine, type LogLine, type PlayerId } from "@perfidia/protocol";
import fc from "fast-check";
import { createAnnotationFold } from "../annotations/index.ts";
import { applySteps, notebookTexts, seatTally } from "../reduce/index.ts";
import { PLANTED, expectNoSecrets, fakeRun, rows } from "../testkit.test.ts";
import { createSpectatorFold, foldLog } from "./fold.ts";

const LONG = 180_000;

const headerOf = (lines: readonly LogLine[]): HeaderLine => {
  const h = lines[0];
  if (h?.k !== "header") throw new Error("no header");
  return h;
};

/** A reader of a growing file: complete lines only, the partial remainder kept for later. */
class Tail {
  private rest = "";
  feed(chunk: string): LogLine[] {
    const text = this.rest + chunk;
    const cut = text.lastIndexOf("\n");
    if (cut < 0) {
      this.rest = text;
      return [];
    }
    this.rest = text.slice(cut + 1);
    return rows(text.slice(0, cut + 1)).map((r) => LogLineSchema.parse(JSON.parse(r)));
  }
}

describe("a fold that follows a fake arena run while it is written", () => {
  test(
    "ends with the steps and the frame of a fold of the whole file (chunks cut anywhere)",
    async () => {
      const run = await fakeRun({ days: 1, seed: 3 });
      const whole = foldLog(run.lines, { match: "fake" });
      expect([whole.status, whole.verified().ok, whole.gatewayDrift()]).toEqual([
        "ended",
        true,
        null,
      ]);
      const text = run.text;
      fc.assert(
        fc.property(
          fc.uniqueArray(fc.integer({ min: 1, max: text.length - 1 }), {
            minLength: 5,
            maxLength: 60,
          }),
          (cuts) => {
            const at = [0, ...cuts.toSorted((a, b) => a - b), text.length];
            const tail = new Tail();
            let fold: ReturnType<typeof createSpectatorFold> | null = null;
            let seen = 0;
            for (let i = 1; i < at.length; i += 1) {
              for (const line of tail.feed(text.slice(at[i - 1], at[i]))) {
                if (fold === null) fold = createSpectatorFold(headerOf([line]), { match: "fake" });
                else fold.push(line);
              }
              // A client reading between chunks sees a consistent prefix.
              if (fold !== null && fold.steps.length > seen) {
                seen = fold.steps.length;
                const first = fold.keyframes[0]?.frame;
                if (first === undefined) throw new Error("no keyframe 0");
                expect(canonicalJson(applySteps(first, fold.steps))).toBe(
                  canonicalJson(fold.frame()),
                );
              }
            }
            expect(fold?.lastSeq).toBe(run.lines.length - 1);
            expect(JSON.stringify(fold?.steps)).toBe(JSON.stringify(whole.steps));
            expect(canonicalJson(fold?.frame())).toBe(canonicalJson(whole.frame()));
          },
        ),
        { numRuns: 4 },
      );
    },
    LONG,
  );

  test(
    "LLM turns are importance-1 items; a message names the turn it was sent in",
    async () => {
      const run = await fakeRun({ days: 1, seed: 3 });
      const fold = foldLog(run.lines, { match: "fake" });
      const items = fold.steps.flatMap((s) => s.items ?? []);
      const turns = items.filter((i) => i.k === "turn");
      const llm = turns.filter((t) => t.llm);
      expect(llm.length).toBeGreaterThan(0);
      expect(llm.every((t) => t.importance === 1 && t.thought !== null)).toBe(true);
      expect(turns.filter((t) => !t.llm).every((t) => t.importance === 0)).toBe(true);
      for (const m of items) {
        if (m.k !== "message" || m.turn === null) continue;
        const turn = turns.find((t) => t.seat === m.from && t.turn === m.turn);
        expect(turn?.messages).toContain(m.message);
      }
      // The seats carry their thoughts and the controller labels of the header.
      const header = headerOf(run.lines);
      for (const seat of Object.values(fold.frame().seats)) {
        expect(seat.controller).toBe(header.controllers[seat.seat] ?? "");
      }
      const t0 = performance.now();
      foldLog(run.lines, { match: "fake" });
      const ms = Math.round(performance.now() - t0);
      const bytes = JSON.stringify(fold.steps).length;
      console.log(
        `1-day fake arena run: ${run.lines.length} lines folded in ${ms} ms; ${fold.steps.length} steps (${bytes} bytes, ${Bun.gzipSync(JSON.stringify(fold.steps)).length} gzipped), ${fold.moments.length} moments, frame ${JSON.stringify(fold.frame()).length} bytes`,
      );
    },
    LONG,
  );
});

describe("the dossier's series on a fake run", () => {
  test(
    "a point per checkpoint, the notebook's versions ending at the notebook now, the record",
    async () => {
      const run = await fakeRun({ days: 1, seed: 3 });
      const fold = foldLog(run.lines, { match: "fake" });
      const items = fold.steps.flatMap((s) => s.items ?? []);
      const ckpts = run.lines.flatMap((l) => (l.k === "ckpt" || l.k === "end" ? [l.t] : []));
      const notes = run.lines.filter((l) => l.k === "note");
      expect(ckpts.length).toBe(24);
      expect(notes.length).toBeGreaterThan(0);
      const header = headerOf(run.lines);
      for (const { id } of header.setup.seats) {
        expect(fold.hourly(id).map((p) => p.t)).toEqual(ckpts);
        const h = fold.notebook(id);
        expect(h.versions).toHaveLength(h.total);
        expect(notebookTexts(h)?.at(-1) ?? "").toBe(fold.notes(id) ?? "");
        const tally = seatTally(items, id);
        expect(fold.counts(id)).toEqual({
          turns: tally.turns,
          messagesSent: tally.messagesSent,
          messagesReceived: tally.messagesReceived,
        });
        expect([tally.betrayalsCommitted, tally.betrayalsSuffered]).toEqual([0, 0]);
      }
      const llm = header.setup.seats.filter((s) =>
        (header.controllers[s.id] ?? "").startsWith("llm:"),
      );
      expect(llm.some((s) => fold.notebook(s.id).total > 1)).toBe(true);
      console.log(
        `1-day fake arena run dossier series: notebook versions ${header.setup.seats.map((s) => `${s.id} ${fold.notebook(s.id).total}`).join(", ")}`,
      );
    },
    LONG,
  );
});

describe("the results of the LLM turns", () => {
  test(
    "list the turn's calls in the order of its replies, with the turn's rejections",
    async () => {
      const run = await fakeRun({ days: 1, seed: 3 });
      const fold = foldLog(run.lines, { match: "fake" });
      const turns = fold.steps
        .flatMap((s) => s.items ?? [])
        .flatMap((i) => (i.k === "turn" ? [i] : []));
      expect(turns.filter((t) => !t.llm).every((t) => t.results === undefined)).toBe(true);
      const llm = turns.filter((t) => t.llm);
      expect(llm.length).toBeGreaterThan(20);
      let calls = 0;
      for (const t of llm) {
        const results = t.results ?? [];
        // The replies' tool calls, round by round; an accepted end_turn writes no line.
        const replied = run.replies
          .filter((r) => r.seat === t.seat && r.turn === t.turn && r.kind === "round")
          .toSorted((a, b) => a.round - b.round)
          .flatMap((r) => r.calls.map((c) => c.name))
          .filter((name) => name !== "end_turn");
        expect([t.seat, t.turn, results.map((r) => r.tool)]).toEqual([t.seat, t.turn, replied]);
        const rejected = t.rejected.reduce((n, r) => n + r.count, 0);
        expect(results.reduce((n, r) => n + r.items - r.ok, 0)).toBe(rejected);
        calls += results.length;
      }
      console.log(`1-day fake arena run: ${llm.length} LLM turns, ${calls} calls with verdicts`);
    },
    LONG,
  );
});

describe("annotations of the LLM turns", () => {
  test(
    "every LLM turn has its rounds, fake reasoning and costs; complete once a later turn exists",
    async () => {
      const run = await fakeRun({ days: 1, seed: 3 });
      const notes = createAnnotationFold();
      for (const line of run.calls) notes.call(line);
      for (const line of run.replies) notes.reply(line);
      const llmSeats = new Set(run.calls.flatMap((l) => (l.k === "llm_call" ? [l.seat] : [])));
      const turnLines = run.lines.filter(
        (l): l is Extract<LogLine, { k: "turn" }> => l.k === "turn" && llmSeats.has(l.seat),
      );
      expect(turnLines.length).toBeGreaterThan(10);
      for (const turn of turnLines) {
        const a = notes.turn(turn.seat, turn.turn, { final: true });
        if (a === null) throw new Error(`no annotation for ${turn.seat} turn ${turn.turn}`);
        expect(a.complete).toBe(true);
        expect(a.rounds.filter((r) => r.kind === "round")).toHaveLength(turn.rounds);
        expect(a.rounds.every((r) => r.reasoning[0]?.startsWith("Fake reasoning:") === true)).toBe(
          true,
        );
        const calls = run.calls.filter(
          (l) => l.k === "llm_call" && l.seat === turn.seat && l.turn === turn.turn,
        );
        const cost = calls.reduce((n, l) => n + (l.k === "llm_call" ? l.costNanoUsd : 0), 0);
        expect(a.rounds.reduce((n, r) => n + r.costNanoUsd, 0)).toBe(cost);
        // Without `final`, a turn is complete only once a later turn of the seat has side lines.
        const last = Math.max(...notes.turns(turn.seat));
        expect(notes.turn(turn.seat, turn.turn)?.complete).toBe(turn.turn < last);
      }
      const p1 = notes.spend("p1");
      const lastP1 = run.calls.findLast((l) => l.k === "llm_call" && l.seat === "p1");
      expect(p1?.spentNanoUsd).toBe(lastP1?.k === "llm_call" ? lastP1.seatSpentNanoUsd : -1);
      const hidden = createAnnotationFold({ costs: false, reasoning: false });
      for (const line of run.calls) hidden.call(line);
      for (const line of run.replies) hidden.reply(line);
      const first = turnLines[0];
      if (first === undefined) throw new Error("no LLM turn");
      const h = hidden.turn(first.seat, first.turn);
      expect(h?.rounds.every((r) => r.costNanoUsd === 0 && r.reasoning.length === 0)).toBe(true);
      expect([h?.spentNanoUsd, h?.capNanoUsd, hidden.spend("p1")]).toEqual([null, null, null]);
    },
    LONG,
  );

  test(
    "refusal categories and error kinds are kept; their explanations, messages and request ids never",
    async () => {
      const run = await fakeRun({ days: 1, seed: 4, secrets: true });
      const raw = run.calls.map((l) => JSON.stringify(l)).join("\n");
      for (const p of Object.values(PLANTED)) expect([p, raw.includes(p)]).toEqual([p, true]);
      const notes = createAnnotationFold();
      for (const line of run.calls) notes.call(line);
      for (const line of run.replies) notes.reply(line);
      const seats: PlayerId[] = ["p1", "p2", "p3", "p4"];
      const all = seats.flatMap((seat) =>
        notes.turns(seat).map((t) => notes.turn(seat, t, { final: true })),
      );
      expect(all.some((a) => a?.rounds.some((r) => r.refusal === "cyber") === true)).toBe(true);
      expect(all.some((a) => a?.rounds.some((r) => r.errors.includes("overloaded")) === true)).toBe(
        true,
      );
      const header = headerOf(run.lines);
      const fold = foldLog(run.lines, { match: "fake" });
      expectNoSecrets(
        { annotations: all, steps: fold.steps, keyframes: fold.keyframes, moments: fold.moments },
        {
          idKey: header.setup.idKey,
          seed: header.setup.seed,
          planted: [...Object.values(PLANTED), "fake-1"],
        },
      );
    },
    LONG,
  );
});

describe("performance on a 7-day fake arena run (PERFIDIA_BENCH=1)", () => {
  test.skipIf(process.env["PERFIDIA_BENCH"] !== "1")(
    "fold time, step and frame sizes",
    async () => {
      const run = await fakeRun({ days: 7, seed: 2 });
      const t0 = performance.now();
      const fold = foldLog(run.lines, { match: "fake7" });
      const ms = Math.round(performance.now() - t0);
      const steps = JSON.stringify(fold.steps);
      const frame = JSON.stringify(fold.frame());
      const perLine: number[] = [];
      const again = createSpectatorFold(headerOf(run.lines), { match: "fake7" });
      for (const line of run.lines.slice(1)) {
        const s = performance.now();
        again.push(line);
        perLine.push(performance.now() - s);
      }
      perLine.sort((a, b) => a - b);
      const p95 = perLine[Math.floor(perLine.length * 0.95)] ?? 0;
      console.log(
        `7-day fake arena run: ${run.lines.length} lines folded in ${ms} ms (p95 per line ${p95.toFixed(3)} ms); ${fold.steps.length} steps: ${steps.length} bytes, ${Bun.gzipSync(steps).length} gzipped; ${fold.keyframes.length} keyframes; frame ${frame.length} bytes, ${Bun.gzipSync(frame).length} gzipped; status ${fold.status}`,
      );
      expect(fold.verified().ok).toBe(true);
    },
    600_000,
  );
});
